CREATE OR REPLACE FUNCTION jfn()
RETURNS STRING
LANGUAGE JAVA
HANDLER = 'JavaFn.fn'
AS $$
class JavaFn{
  public static String fn(){
    return "hello";
  }
}
$$

CREATE OR REPLACE FUNCTION greet(name STRING)
RETURNS STRING
LANGUAGE JAVA
HANDLER = 'Greeter.greet'
AS $$
class Greeter {
  public static String greet(String name) {
    return "Hello, " + name;
  }
}
$$

CREATE OR REPLACE FUNCTION double_value(x INTEGER)
RETURNS INTEGER
LANGUAGE JAVA
HANDLER = 'Math.doubleValue'
AS $$
class Math {
  public static int doubleValue(int x) {
    return x * 2;
  }
}
$$

CREATE OR REPLACE FUNCTION add_numbers(a INTEGER, b INTEGER)
RETURNS INTEGER
LANGUAGE JAVA
HANDLER = 'Calculator.add'
AS $$
class Calculator {
  public static int add(int a, int b) {
    return a + b;
  }
}
$$

CREATE OR REPLACE FUNCTION is_even(n INTEGER)
RETURNS BOOLEAN
LANGUAGE JAVA
HANDLER = 'NumberUtils.isEven'
AS $$
class NumberUtils {
  public static boolean isEven(int n) {
    return n % 2 == 0;
  }
}
$$

CREATE OR REPLACE FUNCTION format_name(firstname STRING, lastname STRING)
RETURNS STRING
LANGUAGE JAVA
HANDLER = 'Formatter.formatName'
AS $$
class Formatter {
  public static String formatName(String firstname, String lastname) {
    return lastname + ", " + firstname;
  }
}
$$

CREATE OR REPLACE FUNCTION factorial(n INTEGER)
RETURNS INTEGER
LANGUAGE JAVA
HANDLER = 'MathUtils.factorial'
AS $$
class MathUtils {
  public static int factorial(int n) {
    if (n <= 1) {
      return 1;
    }
    int result = 1;
    for (int i = 2; i <= n; i++) {
      result *= i;
    }
    return result;
  }
}
$$

